public void solve() {    
    int n = in.nextInt(), m = in.nextInt();
    long inf = Long.MAX_VALUE;
    long[][] dist = new long[n][n];

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) {
                dist[i][j] = 0;
            } else {
                dist[i][j] = inf;
            }
        }
    }

    for (int i = 0; i < m; i++) {
        int u = in.nextInt(), v = in.nextInt();
        long w = in.nextLong();
        --u; --v;
        dist[u][v] = Math.min(dist[u][v], w);
    }

    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (dist[i][k] < inf && dist[k][j] < inf) {
                    dist[i][j] = Math.min(dist[i][j], dist[i][k] + dist[k][j]);
                }
            }
        }
    }

    long[][] dp = new long[1 << n][n];
    for (int i = 0; i < (1 << n); i++) {
        for (int j = 0; j < n; j++) {
            dp[i][j] = inf;
        }
    }

    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 0;
    }

    for (int i = 0; i < (1 << n); i++) {
        for (int j = 0; j < n; j++) {
            if (((i >> j) & 1) == 1) {
                if (dp[i][j] == inf) continue;
                for (int k = 0; k < n; k++) {
                    if (((i >> k) & 1) == 0 && dist[j][k] < inf) {
                        dp[i | (1 << k)][k] = Math.min(dp[i | (1 << k)][k], dp[i][j] + dist[j][k]);
                    }
                }
            }
        }
    }

    long minCost = inf;
    for (int i = 0; i < n; i++) {
        minCost = Math.min(minCost, dp[(1 << n) - 1][i]);
    }

    out.println(minCost == inf ? no : minCost);
}
